package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.widget.*;import java.io.*;
public class GlobalTransferActivity extends Activity {
 boolean exporting,busy;GlobalArchive.Staged staged;TextView status;
 static void launch(Activity a,boolean export){a.startActivity(new Intent(a,GlobalTransferActivity.class).putExtra("export",export));}
 public void onCreate(Bundle b){super.onCreate(b);Ui.window(this);if(TapService.instance!=null)TapService.instance.stopSession("Global backup");exporting=getIntent().getBooleanExtra("export",false);LinearLayout root=Ui.column(this);root.setPadding(Ui.dp(this,24),Ui.dp(this,48),Ui.dp(this,24),Ui.dp(this,24));root.setBackgroundColor(Ui.BG);root.addView(Ui.label(this,exporting?"Export everything":"Restore everything",26,Ui.CREAM));status=Ui.label(this,"All actions • 21 preset slots • layouts • settings",16,Ui.MUTED);root.addView(status);setContentView(root);if(b!=null){status.setText("File operation interrupted. Return and try again.");Button back=Ui.button(this,"Back",true);root.addView(back);back.setOnClickListener(v->finish());return;}Intent i=new Intent(exporting?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(exporting?"application/zip":"*/*");if(exporting)i.putExtra(Intent.EXTRA_TITLE,"AutoBash-everything.autobash.zip");try{startActivityForResult(i,1);}catch(ActivityNotFoundException e){error("No file picker is available.");}}
 protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(code!=RESULT_OK||data==null){finish();return;}Uri uri=data.getData();busy=true;status.setText(exporting?"Saving the whole app setup…":"Checking the backup…");new Thread(()->{try{if(exporting){try(OutputStream o=getContentResolver().openOutputStream(uri,"wt")){GlobalArchive.exportAll(this,o);}runOnUiThread(()->{busy=false;status.setText("Everything exported.");sheet(new AlertDialog.Builder(this).setTitle("Backup saved").setMessage("This file contains all action presets, regions, timelines, Auto Tap layouts and portable settings. Restore it from Home → Back up or restore everything.").setPositiveButton("Done",(d,w)->finish()).create());});}else{try(InputStream in=getContentResolver().openInputStream(uri)){staged=GlobalArchive.stage(this,in);}runOnUiThread(()->{busy=false;sheet(new AlertDialog.Builder(this).setTitle("Replace the whole app setup?").setMessage(staged.count()+" images across all 21 slots, plus layouts and settings. Current collections will be replaced. Export your current setup first if you want to keep it. Actions remain OFF after restore.").setNegativeButton("Cancel",(d,w)->finish()).setPositiveButton("Replace & restore",(d,w)->install()).setOnCancelListener(d->finish()).create());});}}catch(Exception e){runOnUiThread(()->{busy=false;error(e.getMessage());});}},"global-backup").start();}
 void install(){busy=true;status.setText("Restoring…");new Thread(()->{try{GlobalArchive.install(this,staged);runOnUiThread(()->{busy=false;Toast.makeText(this,"Restored. Review your setup before enabling actions.",Toast.LENGTH_LONG).show();finish();});}catch(Exception e){runOnUiThread(()->{busy=false;error(e.getMessage());});}},"global-restore").start();}
 void sheet(AlertDialog d){if(isFinishing()||isDestroyed()){if(staged!=null&&!busy)staged.close();return;}d.show();Ui.sheet(d);}
 void error(String s){if(isDestroyed())return;sheet(new AlertDialog.Builder(this).setTitle("Backup could not finish").setMessage(s).setPositiveButton("Back",(d,w)->finish()).create());}
 public void onBackPressed(){if(!busy)finish();else Toast.makeText(this,"Please wait for the file operation.",Toast.LENGTH_SHORT).show();}
 protected void onDestroy(){if(staged!=null&&!busy)staged.close();super.onDestroy();}
}
